#!/usr/bin/env python3### ---------------------------------------- ###def check_assembly(path):        contigs = open(path, 'r').read()        if contigs.startswith('>'):            contigs = [''.join(seq.split('\n')[1:]) for seq in contigs.split('>') if len(seq)]                n_contigs = len(contigs)                contigs_len = [len(c) for c in contigs]                return n_contigs, contigs_len        else:                return 0, 0### ------------------MAIN------------------ ###import pandas as pdfrom os import listdirfrom os.path import exists, isdirfrom sys import argv### Parse foldersif '--results_dir' in argv:    main_results_dir = argv[argv.index('--results_dir') + 1]else:    main_results_dir = 'assembly_results'samples = [subdir for subdir in listdir(main_results_dir) if isdir(f'{main_results_dir}/{subdir}')]### Check samples' resultssummary_header = [    'sample',    'reference_based_assembly',    'reference_based_assembly_contigs',    'reference_based_assembly_lenghts',    'full_reads_assembly',    'full_reads_assembly_contigs',    'full_reads_assembly_lenghts',    'subsample_assemblies',    'subsample_assemblies_contigs',    'subsample_assemblies_lenghts',    'subsample_trycycler_consensus_assemblies',    'subsample_trycycler_consensus_assemblies_contigs',    'subsample_trycycler_consensus_assemblies_lenghts',    'subsample_custom_consensus_assemblies',    'subsample_custom_consensus_assemblies_contigs',    'subsample_custom_consensus_assemblies_lenghts']summary = []for s in samples:        # Init sample summary        s_summary = [s]        # Check if the reference-based alignment was successfull        subdir = f'{main_results_dir}/{s}/alignment_based_assembly'        if exists(subdir):                target_file = f'{subdir}/{s}_consensus.fasta'        else:                target_file = 'STUB'        if exists(target_file):                c, c_lens = check_assembly(target_file)                success = 1            else:                c, c_lens = 0, 0                success = 0        s_summary.extend([success, c, str(c_lens)])        # Check if assembly with all reads was successfull        subdir = f'{main_results_dir}/{s}/deconcatenated_assembly'        if exists(subdir):                target_file = [f'{subdir}/{f}' for f in listdir(subdir) if f'{s}_allreads' in f and f.endswith('.deconcatenated.fasta')]        else:                target_file = 'STUB'        if len(target_file):                target_file = target_file[0]                c, c_lens = check_assembly(target_file)                success = 1            else:                c, c_lens = 0, 0                success = 0        s_summary.extend([success, c, str(c_lens)])        ### Count subsample assemblies        subdir = f'{main_results_dir}/{s}/deconcatenated_assembly'        if exists(subdir):                target_files = [f'{subdir}/{f}' for f in listdir(subdir) if f'{s}_sample' in f and f.endswith('.deconcatenated.fasta')]        else:                target_files = []        if len(target_files):                checks = [check_assembly(tf) for tf in target_files]                checks = [ck for ck in checks if ck[0] != 0]                c = '; '.join([str(ck[0]) for ck in checks]) if len(checks) else 0                c_lens = '; '.join([str(ck[1]) for ck in checks]) if len(checks) else 0                success = len(checks)            else:                c, c_lens = 0, 0                success = 0        s_summary.extend([success, c, str(c_lens)])        ### Count trycycler consensus assemblies        subdir = f'{main_results_dir}/{s}/consensus_assembly'        if exists(subdir):                target_files = [f'{subdir}/{f}' for f in listdir(subdir) if f'{s}_cluster' in f and f.endswith('_trycycler.consensus.polished.contigs.fasta')]        else:                target_files = []        if len(target_files):                checks = [check_assembly(tf) for tf in target_files]                checks = [ck for ck in checks if ck[0] != 0]                c = '; '.join([str(ck[0]) for ck in checks]) if len(checks) else 0                c_lens = '; '.join([str(ck[1]) for ck in checks]) if len(checks) else 0                success = len(checks)            else:                c, c_lens = 0, 0                success = 0        s_summary.extend([success, c, str(c_lens)])        ### Count custom consensus assemblies        subdir = f'{main_results_dir}/{s}/consensus_assembly'        if exists(subdir):                target_files = [f'{subdir}/{f}' for f in listdir(subdir) if f.endswith('_custom.consensus.contigs.fasta')]        else:                target_files = []        if len(target_files):                checks = [check_assembly(tf) for tf in target_files]                checks = [ck for ck in checks if ck[0] != 0]                c = '; '.join([str(ck[0]) for ck in checks]) if len(checks) else 0                c_lens = '; '.join([str(ck[1]) for ck in checks]) if len(checks) else 0                success = len(checks)            else:                c, c_lens = 0, 0                success = 0        s_summary.extend([success, c, str(c_lens)])        # Store data        summary.append(s_summary)summary = pd.DataFrame(summary, columns=summary_header)summary = summary.sort_values(by='sample')### Save summary to filesummary.to_csv(f'{main_results_dir}/summary.tsv', sep='\t', index=False)